-- Nexmark q21 on flink, BLACKHOLE sink variant. Add channel id: a CASE over a
-- string column, per record.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (
  `auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING, `url` STRING, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-bid',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-q21bh-bid',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE sink_q21 (`auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING) WITH ('connector' = 'blackhole');
INSERT INTO sink_q21
SELECT auction, bidder, price, CASE WHEN channel = 'apple' THEN '0' WHEN channel = 'google' THEN '1' WHEN channel = 'facebook' THEN '2' WHEN channel = 'baidu' THEN '3' ELSE channel END AS channel FROM bid;
